cat > efprobe.csproj <<'EOF'
<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup><OutputType>Exe</OutputType><TargetFramework>net10.0</TargetFramework><Nullable>enable</Nullable><ImplicitUsings>enable</ImplicitUsings></PropertyGroup>
  <ItemGroup><PackageReference Include="Microsoft.EntityFrameworkCore.SqlServer" Version="10.0.5" /></ItemGroup>
</Project>
EOF
cat > Program.cs <<'EOF'
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;

var password = File.ReadAllText("../.sa_password").Trim();
var options = new DbContextOptionsBuilder<ProbeContext>()
    .UseSqlServer($"Server=127.0.0.1,14333;Database=relay;User Id=sa;Password={password};TrustServerCertificate=True")
    .LogTo(Console.WriteLine, new[] { DbLoggerCategory.Database.Command.Name }, LogLevel.Information)
    .EnableSensitiveDataLogging()
    .Options;
using var db = new ProbeContext(options);

var tz = TimeZoneInfo.FindSystemTimeZoneById("America/New_York");
var windows = new List<object>();
for (var monday = new DateTime(2026, 1, 26); monday <= new DateTime(2026, 7, 20); monday = monday.AddDays(7))
{
    var start = TimeZoneInfo.ConvertTimeToUtc(monday, tz);
    var end = TimeZoneInfo.ConvertTimeToUtc(monday.AddDays(7), tz);
    windows.Add(new { start, end });
}
var windowsJson = JsonSerializer.Serialize(windows);
Console.WriteLine(windowsJson[..120]);
var accountId = 6;
foreach (var eventType in new string?[] { null, "call_received" })
{
    var rows = await db.Database.SqlQuery<WeeklyLocationCount>($"""
        SELECT deduplicated.location AS Location, deduplicated.window_start AS WindowStart, COUNT(*) AS EventCount
        FROM (
            SELECT DISTINCT windows.window_start, events.location, events.event_type,
                   events.occurred_at, events.duration_seconds, events.outcome
            FROM OPENJSON({windowsJson}) WITH (window_start datetime2 '$.start', window_end datetime2 '$.end') AS windows
            JOIN activity_events AS events
              ON events.account_id = {accountId}
             AND events.occurred_at >= windows.window_start
             AND events.occurred_at <  windows.window_end
            WHERE {eventType} IS NULL OR events.event_type = {eventType}
        ) AS deduplicated
        GROUP BY deduplicated.location, deduplicated.window_start
        """).ToListAsync();
    Console.WriteLine($"RESULT type={eventType ?? "all"} rows={rows.Count} total={rows.Sum(r => r.EventCount)} firstKind={rows[0].WindowStart.Kind}");
    foreach (var r in rows.Where(r => r.Location == "Site A").OrderBy(r => r.WindowStart).Take(3)) Console.WriteLine($"ROW {r.Location} {r.WindowStart:o} {r.EventCount}");
}
var anchor = await db.Database.SqlQuery<DataAnchor>($"SELECT MIN(occurred_at) AS FirstOccurredAt, MAX(occurred_at) AS LastOccurredAt FROM activity_events").SingleAsync();
Console.WriteLine($"ANCHOR {anchor}");

public sealed record WeeklyLocationCount(string Location, DateTime WindowStart, int EventCount);
public sealed record DataAnchor(DateTime? FirstOccurredAt, DateTime? LastOccurredAt);
public sealed class ProbeContext(DbContextOptions<ProbeContext> options) : DbContext(options);
EOF
